-- Immutable inventory and finalized annual journal protection. Explicit runner only.
DELIMITER $$
CREATE TRIGGER iv_gl_finalized_run_no_update BEFORE UPDATE ON financial_year_close_runs FOR EACH ROW BEGIN IF OLD.status='FINALIZED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_FINALIZED_RUN_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_journal_no_update BEFORE UPDATE ON journal_entries FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=OLD.id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=OLD.id OR r.opening_journal_entry_id=OLD.id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_LINKED_JOURNAL_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_detail_no_update BEFORE UPDATE ON journal_entry_details FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=OLD.journal_entry_id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=OLD.journal_entry_id OR r.opening_journal_entry_id=OLD.journal_entry_id))) OR (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=NEW.journal_entry_id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=NEW.journal_entry_id OR r.opening_journal_entry_id=NEW.journal_entry_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_LINKED_JOURNAL_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_journal_no_delete BEFORE DELETE ON journal_entries FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=OLD.id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=OLD.id OR r.opening_journal_entry_id=OLD.id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_LINKED_JOURNAL_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_detail_no_delete BEFORE DELETE ON journal_entry_details FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=OLD.journal_entry_id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=OLD.journal_entry_id OR r.opening_journal_entry_id=OLD.journal_entry_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_LINKED_JOURNAL_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_detail_no_insert BEFORE INSERT ON journal_entry_details FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM iv_operations o JOIN JSON_TABLE(o.result,'$.journals[*]' COLUMNS(journal_id BIGINT PATH '$.id')) j ON j.journal_id=NEW.journal_entry_id WHERE o.action IN ('GL_POST','GL_CUTOVER')) OR EXISTS (SELECT 1 FROM financial_year_close_runs r WHERE r.status='FINALIZED' AND (r.closing_journal_entry_id=NEW.journal_entry_id OR r.opening_journal_entry_id=NEW.journal_entry_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_LINKED_JOURNAL_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_account_no_update BEFORE UPDATE ON accounts FOR EACH ROW BEGIN IF (NOT(NEW.id <=> OLD.id) OR NOT(NEW.company_id <=> OLD.company_id) OR NOT(NEW.account_type <=> OLD.account_type) OR NOT(NEW.status <=> OLD.status)) AND EXISTS (SELECT 1 FROM iv_operations WHERE company_id=OLD.company_id AND action='GL_ROLE' AND JSON_UNQUOTE(JSON_EXTRACT(result,'$.account_id'))=CAST(OLD.id AS CHAR)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_ROLE_ACCOUNT_IMMUTABLE'; END IF; END$$
CREATE TRIGGER iv_gl_account_no_delete BEFORE DELETE ON accounts FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM iv_operations WHERE company_id=OLD.company_id AND action='GL_ROLE' AND JSON_UNQUOTE(JSON_EXTRACT(result,'$.account_id'))=CAST(OLD.id AS CHAR)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='IV_GL_ROLE_ACCOUNT_IMMUTABLE'; END IF; END$$
DELIMITER ;
